import{_ as t,o,c as a,ag as i}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common issues and solutions for Muxit — server, devices, scripts, dashboards, and AI.","frontmatter":{"title":"Troubleshooting","description":"Common issues and solutions for Muxit — server, devices, scripts, dashboards, and AI."},"headers":[],"relativePath":"guides/troubleshooting.md","filePath":"guides/troubleshooting.md"}'),s={name:"guides/troubleshooting.md"};function n(r,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Solutions for common issues you may encounter when using Muxit.</p><h2 id="server-issues" tabindex="-1">Server Issues <a class="header-anchor" href="#server-issues" aria-label="Permalink to &quot;Server Issues&quot;">​</a></h2><h3 id="server-won-t-start" tabindex="-1">Server Won&#39;t Start <a class="header-anchor" href="#server-won-t-start" aria-label="Permalink to &quot;Server Won&#39;t Start&quot;">​</a></h3><p><strong>&quot;Port 8765 already in use&quot;</strong> Another process is using the default port. Either:</p><ul><li>Stop the other process (possibly another Muxit instance)</li><li>Use a different port: <code>node start.js server --port=9000</code></li></ul><p><strong><code>dotnet: command not found</code></strong> The .NET 9.0 SDK is not installed. Install it from <a href="https://dotnet.microsoft.com/download" target="_blank" rel="noreferrer">dotnet.microsoft.com/download</a>. Verify with <code>dotnet --version</code>.</p><p><strong><code>node: command not found</code></strong> Node.js is not installed. Install Node.js 18+ from <a href="https://nodejs.org/" target="_blank" rel="noreferrer">nodejs.org</a>.</p><p><strong>Build errors</strong> Make sure you&#39;re using .NET 9.0 (not 8.0 or earlier). Run <code>dotnet --version</code> to check. If you haven&#39;t built yet, run <code>node build.js</code> first.</p><p><strong>macOS: &quot;muxit cannot be opened because the developer cannot be verified&quot;</strong> macOS release builds aren&#39;t code-signed or notarized yet, so Gatekeeper quarantines the downloaded binary. The install script clears this automatically. If you unpacked a release archive by hand, run it once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/muxit-install-dir</span></span></code></pre></div><p>Then launch <code>./muxit</code> again. (You can also right-click the binary in Finder → <strong>Open</strong> → <strong>Open</strong> to approve it once.)</p><p><strong>macOS: camera connector won&#39;t capture</strong> On macOS, USB webcams and Onvif/RTSP cameras capture through the system <code>ffmpeg</code> binary (the TestDevice video stream is fully self-contained). If capture fails:</p><ul><li>Install ffmpeg: <code>brew install ffmpeg</code>.</li><li>For USB webcams, grant camera access under <strong>System Settings → Privacy &amp; Security → Camera</strong> (a CLI launched from Terminal inherits Terminal&#39;s grant). The default <code>device</code> index is <code>0</code>; try other indices if you have multiple cameras.</li></ul><p><strong>macOS: &quot;Recording is not supported on macOS&quot;</strong> Expected. Video recording uses OpenCV&#39;s <code>VideoWriter</code>, which has no macOS native runtime, so <code>record</code> / <code>recordStart</code> are blocked on macOS. Live streaming and snapshots (including flips and digital zoom) work. The optional Vision <em>detection</em> driver is likewise OpenCV-based and unavailable on macOS — record or run local CV detection on a Windows or Linux host.</p><h3 id="can-t-see-the-web-ui" tabindex="-1">Can&#39;t See the Web UI <a class="header-anchor" href="#can-t-see-the-web-ui" aria-label="Permalink to &quot;Can&#39;t See the Web UI&quot;">​</a></h3><p><strong>Browser shows blank page</strong> The web UI needs to be built before the server can serve it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><p><strong>Wrong URL</strong> Muxit runs on port <strong>8765</strong> by default: <code>http://127.0.0.1:8765</code>. If you used <code>--port=9000</code>, use that port instead.</p><p><strong>Firewall blocking</strong> On Windows, open <strong>Settings → Privacy &amp; security → Windows Security → Firewall &amp; network protection → Allow an app through firewall</strong> and allow <code>muxit.exe</code> on your active network profile. For a diagnostic view with copy-paste PowerShell fix commands, open <strong>Settings → Server → Network Diagnostics</strong> inside Muxit.</p><p><strong>Browser cache</strong> Try a hard refresh (<code>Ctrl+Shift+R</code>) or open in an incognito/private window.</p><hr><h2 id="viewing-server-logs" tabindex="-1">Viewing Server Logs <a class="header-anchor" href="#viewing-server-logs" aria-label="Permalink to &quot;Viewing Server Logs&quot;">​</a></h2><p>Muxit captures every console line into an in-memory ring buffer (the last 500 entries) and exposes it through a live log viewer at <code>/logs.html</code>.</p><h3 id="three-ways-to-open-the-viewer" tabindex="-1">Three ways to open the viewer <a class="header-anchor" href="#three-ways-to-open-the-viewer" aria-label="Permalink to &quot;Three ways to open the viewer&quot;">​</a></h3><ul><li><strong>System tray</strong> → &quot;View Logs&quot; — works even if the GUI is closed.</li><li><strong>Title bar</strong> → View → Server Logs.</li><li><strong>Status bar</strong> → &quot;Logs&quot; button, next to &quot;Panel&quot;.</li></ul><p>All three open <code>/logs.html</code> in a new tab. The page streams new entries via Server-Sent Events (no manual refresh) and supports level filtering (debug/info/warn/error), substring search, pause/resume, and download-as-text.</p><h3 id="multiple-instances-on-one-machine" tabindex="-1">Multiple instances on one machine <a class="header-anchor" href="#multiple-instances-on-one-machine" aria-label="Permalink to &quot;Multiple instances on one machine&quot;">​</a></h3><p>Each Muxit instance runs on its own port (<code>8765</code>, <code>9000</code>, …). The log viewer URL is <code>http://localhost:&lt;port&gt;/logs.html</code>, so each instance shows only its own logs — no cross-talk.</p><h3 id="when-the-http-server-isn-t-reachable" tabindex="-1">When the HTTP server isn&#39;t reachable <a class="header-anchor" href="#when-the-http-server-isn-t-reachable" aria-label="Permalink to &quot;When the HTTP server isn&#39;t reachable&quot;">​</a></h3><p>If the server crashes during boot (port conflict, broken config, exception before Kestrel binds), the live viewer is unreachable. Two fallback files are written per workspace — both overwritten in place, never accumulated:</p><table tabindex="0"><thead><tr><th>File</th><th>Written</th></tr></thead><tbody><tr><td><code>startup.log</code></td><td>On every clean exit (also <code>Ctrl+C</code>, <code>Environment.Exit</code>).</td></tr><tr><td><code>last-crash.log</code></td><td>On unhandled exception.</td></tr></tbody></table><p>Paths:</p><ul><li><strong>Windows</strong>: <code>%LOCALAPPDATA%\\Muxit\\logs\\&lt;workspace-hash&gt;\\</code></li><li><strong>macOS / Linux</strong>: <code>~/.muxit/logs/&lt;workspace-hash&gt;/</code></li></ul><p><code>&lt;workspace-hash&gt;</code> is a 12-character SHA prefix of the workspace path, so two instances on different workspaces never overwrite each other&#39;s files.</p><p>When a <code>last-crash.log</code> is present from a previous run, the system tray adds a one-shot <strong>&quot;Open Last Crash Log&quot;</strong> entry that opens it in the OS default text editor.</p><h3 id="loopback-only" tabindex="-1">Loopback only <a class="header-anchor" href="#loopback-only" aria-label="Permalink to &quot;Loopback only&quot;">​</a></h3><p><code>/api/logs</code>, <code>/api/logs/stream</code>, <code>/api/logs/startup</code>, and <code>/api/logs/last-crash</code> reject non-loopback callers (HTTP 403) — even with a valid remote-access token. A leaked session token cannot be used to scrape diagnostics from a remote host.</p><hr><h2 id="device-connection-issues" tabindex="-1">Device Connection Issues <a class="header-anchor" href="#device-connection-issues" aria-label="Permalink to &quot;Device Connection Issues&quot;">​</a></h2><h3 id="serial-device-not-connecting" tabindex="-1">Serial Device Not Connecting <a class="header-anchor" href="#serial-device-not-connecting" aria-label="Permalink to &quot;Serial Device Not Connecting&quot;">​</a></h3><p><strong>Wrong port name</strong> Open <strong>Device Manager → Ports (COM &amp; LPT)</strong> and note the COM port assigned to your adapter (e.g. <code>COM3</code>, <code>COM4</code>). Unplugging and replugging the cable is the fastest way to spot which entry belongs to your device. Put that port name in the connector&#39;s <code>config.port</code>.</p><p><strong>Baud rate mismatch</strong> Make sure the <code>baudRate</code> in your connector config matches your device. Common rates: 9600, 19200, 38400, 57600, 115200.</p><p><strong>Device not responding</strong></p><ul><li>Check the USB cable is connected</li><li>Try unplugging and replugging the device</li><li>Check if another program (Arduino IDE, PuTTY, screen) has the port open — only one program can use a serial port at a time</li></ul><h3 id="tcp-device-not-connecting" tabindex="-1">TCP Device Not Connecting <a class="header-anchor" href="#tcp-device-not-connecting" aria-label="Permalink to &quot;TCP Device Not Connecting&quot;">​</a></h3><p><strong>Wrong IP or port</strong> Verify the device IP is reachable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.100</span></span></code></pre></div><p><strong>Firewall blocking</strong> Ensure the device&#39;s port is not blocked by a firewall on either end.</p><p><strong>Device not on the same network</strong> Make sure your computer and the device are on the same subnet.</p><hr><h2 id="script-issues" tabindex="-1">Script Issues <a class="header-anchor" href="#script-issues" aria-label="Permalink to &quot;Script Issues&quot;">​</a></h2><h3 id="connector-not-found-error" tabindex="-1">&quot;connector not found&quot; Error <a class="header-anchor" href="#connector-not-found-error" aria-label="Permalink to &quot;&quot;connector not found&quot; Error&quot;">​</a></h3><p>The connector name in your script must match the filename (without <code>.js</code>) in <code>workspace/connectors/</code>:</p><ul><li>File: <code>workspace/connectors/psu.js</code> → Use: <code>connector(&quot;psu&quot;)</code></li><li>File: <code>workspace/connectors/my-device.js</code> → Use: <code>connector(&quot;my-device&quot;)</code></li></ul><p>Also check:</p><ul><li>The connector is <strong>enabled</strong> in the Hardware panel (disabled connectors can&#39;t be accessed)</li><li>You spelled the name correctly (case-sensitive)</li><li>The server has been restarted after creating a new connector file</li></ul><h3 id="require-is-not-defined-or-import-is-not-supported" tabindex="-1">&quot;require is not defined&quot; or &quot;import is not supported&quot; <a class="header-anchor" href="#require-is-not-defined-or-import-is-not-supported" aria-label="Permalink to &quot;&quot;require is not defined&quot; or &quot;import is not supported&quot;&quot;">​</a></h3><p>Muxit scripts run in a <strong>sandboxed environment</strong> with no access to Node.js modules. You cannot use:</p><ul><li><code>require()</code> or <code>import</code></li><li><code>fs</code>, <code>path</code>, <code>net</code>, <code>http</code>, <code>child_process</code></li><li><code>process</code>, <code>global</code>, <code>globalThis</code></li></ul><p>Instead, use the provided globals: <code>connector()</code>, <code>log</code>, <code>emit()</code>, <code>on()</code>, <code>delay()</code>, <code>ai()</code>, etc. See the <a href="/guides/scripts.html">Script Guide</a> for all available functions.</p><h3 id="script-won-t-stop" tabindex="-1">Script Won&#39;t Stop <a class="header-anchor" href="#script-won-t-stop" aria-label="Permalink to &quot;Script Won&#39;t Stop&quot;">​</a></h3><p>Pressing <strong>Stop</strong> ends a script immediately, wherever it is — including in the middle of a <code>delay()</code> or a device call. An endless loop is the normal pattern:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✓ Stops when you click Stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  delay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Scripts with tight loops without <code>delay()</code> can still be stopped — the V8 engine is interrupted — but they burn CPU until then. Code after the loop and <code>finally</code> blocks never run after Stop.</p><h3 id="script-timeout" tabindex="-1">Script Timeout <a class="header-anchor" href="#script-timeout" aria-label="Permalink to &quot;Script Timeout&quot;">​</a></h3><p>Long-running operations (like <code>delay(60000)</code>) are abortable — when you click Stop, <code>delay()</code> resolves immediately. If a script seems stuck, click Stop in the editor toolbar or the Explorer sidebar.</p><h3 id="property-is-read-only-error" tabindex="-1">&quot;property is read-only&quot; Error <a class="header-anchor" href="#property-is-read-only-error" aria-label="Permalink to &quot;&quot;property is read-only&quot; Error&quot;">​</a></h3><p>You&#39;re trying to write to a property that only supports reading. Check the connector schema — properties marked <code>R</code> (read-only) can&#39;t be set. Use the Hardware panel to see property access modes.</p><hr><h2 id="dashboard-issues" tabindex="-1">Dashboard Issues <a class="header-anchor" href="#dashboard-issues" aria-label="Permalink to &quot;Dashboard Issues&quot;">​</a></h2><h3 id="dashboard-not-updating" tabindex="-1">Dashboard Not Updating <a class="header-anchor" href="#dashboard-not-updating" aria-label="Permalink to &quot;Dashboard Not Updating&quot;">​</a></h3><p><strong>Polling not enabled</strong> Properties must have polling enabled to update automatically. In the connector config, add the property to the <code>poll</code> array:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">poll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;voltage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;current&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>Or set <code>poll: true</code> on individual computed properties:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">properties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  power</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> driver.voltage) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> driver.current),</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    poll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p><strong>Wrong binding path</strong> Widget bindings must match exactly:</p><ul><li><code>connector</code> field = connector filename (without <code>.js</code>)</li><li><code>property</code> field = property name from the driver or connector</li></ul><p>Check the Hardware panel to verify the exact property names.</p><p><strong>Connector disabled</strong> Disabled connectors don&#39;t poll or update. Enable it in the Hardware panel.</p><h3 id="widgets-showing-n-a-or-no-data" tabindex="-1">Widgets Showing &quot;N/A&quot; or No Data <a class="header-anchor" href="#widgets-showing-n-a-or-no-data" aria-label="Permalink to &quot;Widgets Showing &quot;N/A&quot; or No Data&quot;">​</a></h3><p>The connector may not be initialized yet, or the property doesn&#39;t exist. Check:</p><ol><li>The connector is listed in the Hardware panel</li><li>The property name is correct (case-sensitive)</li><li>The device is connected and responding</li></ol><h3 id="dashboard-won-t-save" tabindex="-1">Dashboard Won&#39;t Save <a class="header-anchor" href="#dashboard-won-t-save" aria-label="Permalink to &quot;Dashboard Won&#39;t Save&quot;">​</a></h3><p>Make sure editor mode is enabled (Settings &gt; Security &gt; Editor Mode). Without editor mode, file writes are blocked.</p><hr><h2 id="ai-issues" tabindex="-1">AI Issues <a class="header-anchor" href="#ai-issues" aria-label="Permalink to &quot;AI Issues&quot;">​</a></h2><h3 id="ai-chat-not-responding" tabindex="-1">AI Chat Not Responding <a class="header-anchor" href="#ai-chat-not-responding" aria-label="Permalink to &quot;AI Chat Not Responding&quot;">​</a></h3><p><strong>License not active</strong> Muxit AI requires a valid license. Open Settings (gear icon) and check that your license is active under <strong>License</strong>.</p><p><strong>No internet connection</strong> Muxit AI connects to <code>api.muxit.io</code> for AI requests. Check that your machine can reach the internet.</p><p><strong>Model doesn&#39;t support tools</strong> Some models don&#39;t support function calling / tool use. Use a capable model like Claude Sonnet/Opus, GPT-4o, or Gemini 2.0 Flash.</p><h3 id="ai-can-t-see-camera-images" tabindex="-1">AI Can&#39;t See Camera Images <a class="header-anchor" href="#ai-can-t-see-camera-images" aria-label="Permalink to &quot;AI Can&#39;t See Camera Images&quot;">​</a></h3><p>Vision requires:</p><ol><li>A camera connector configured and initialized (Webcam or ONVIF)</li><li>A model that supports vision (Claude Sonnet/Opus, GPT-4o, Gemini)</li><li>The <code>take_snapshot</code> tool to be called</li></ol><h3 id="ai-tool-calls-blocked" tabindex="-1">AI Tool Calls Blocked <a class="header-anchor" href="#ai-tool-calls-blocked" aria-label="Permalink to &quot;AI Tool Calls Blocked&quot;">​</a></h3><p>Tool-call approvals are driven by the current global safety level. In <strong>Observe</strong> and <strong>Assisted</strong> every device write or action may require your approval — click <strong>Allow</strong> in the approval dialog. To skip approvals, change the safety level (via the StatusStrip SafetyChip) to <strong>Active</strong> or <strong>Unrestricted</strong> — but only if you trust the AI&#39;s actions.</p><hr><h2 id="websocket-issues" tabindex="-1">WebSocket Issues <a class="header-anchor" href="#websocket-issues" aria-label="Permalink to &quot;WebSocket Issues&quot;">​</a></h2><h3 id="connection-lost-reconnecting" tabindex="-1">Connection Lost / Reconnecting <a class="header-anchor" href="#connection-lost-reconnecting" aria-label="Permalink to &quot;Connection Lost / Reconnecting&quot;">​</a></h3><p>The WebSocket connection to the server may drop due to:</p><ul><li>Server restart — the browser auto-reconnects</li><li>Network interruption — check your network connection</li><li>Server crash — check the terminal where the server is running for errors</li></ul><p>The status bar at the bottom of the UI shows the connection state.</p><h3 id="not-authenticated-error" tabindex="-1">&quot;Not authenticated&quot; Error <a class="header-anchor" href="#not-authenticated-error" aria-label="Permalink to &quot;&quot;Not authenticated&quot; Error&quot;">​</a></h3><p>If accessing Muxit remotely:</p><ol><li>Make sure remote access is enabled (Settings &gt; Remote Access)</li><li>Enter your password on the login page</li><li>If your session expired (24 hours), log in again</li></ol><p>For local access (localhost), authentication is automatic.</p><hr><h2 id="license-issues" tabindex="-1">License Issues <a class="header-anchor" href="#license-issues" aria-label="Permalink to &quot;License Issues&quot;">​</a></h2><h3 id="connector-limit-reached" tabindex="-1">&quot;Connector limit reached&quot; <a class="header-anchor" href="#connector-limit-reached" aria-label="Permalink to &quot;&quot;Connector limit reached&quot;&quot;">​</a></h3><p>Your license tier limits the number of active connectors. The <strong>TestDevice</strong> doesn&#39;t count against this limit. Options:</p><ul><li>Disable connectors you&#39;re not using (Hardware panel)</li><li>Upgrade your license tier</li></ul><h3 id="trial-expired" tabindex="-1">Trial Expired <a class="header-anchor" href="#trial-expired" aria-label="Permalink to &quot;Trial Expired&quot;">​</a></h3><p>Trial features revert to the free tier when the trial ends. Activate a license key to continue using premium features.</p><h3 id="running-on-free-or-a-paid-feature-stopped" tabindex="-1">Running on Free, or a paid feature stopped <a class="header-anchor" href="#running-on-free-or-a-paid-feature-stopped" aria-label="Permalink to &quot;Running on Free, or a paid feature stopped&quot;">​</a></h3><p>Open the <a href="#viewing-server-logs">server log viewer</a> and search for <code>License</code>. Muxit logs what it concluded about your license at startup and when the daily re-check changes something, so the log says which case you are in: the license was verified (and until when), the subscription ended, there was no valid license proof and Muxit is waiting to re-check online, it is running on downgrade grace (and until when operator mode and the audit log keep working), the machine&#39;s hardware changed enough that the license needs re-activating, or the system clock is behind the last time Muxit ran. The same lines are in <code>startup.log</code> when the server will not come up.</p><p>If activation said the key was accepted but Muxit could not get its signed license, the tier stays Free until it does: paid features unlock only from that signed license, never from the activation reply alone. Muxit retries in the background and on the next start; check the machine&#39;s internet connection, or activate again.</p><hr><h2 id="performance-issues" tabindex="-1">Performance Issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance Issues&quot;">​</a></h2><h3 id="high-cpu-usage" tabindex="-1">High CPU Usage <a class="header-anchor" href="#high-cpu-usage" aria-label="Permalink to &quot;High CPU Usage&quot;">​</a></h3><p>Too many properties being polled too frequently. Reduce the load:</p><ul><li>Lower the poll rate: set <code>polling.connectorRate</code> to 500 (or higher) in the server configuration</li><li>Remove unnecessary properties from the <code>poll</code> array</li><li>Disable unused connectors</li></ul><h3 id="slow-dashboard-updates" tabindex="-1">Slow Dashboard Updates <a class="header-anchor" href="#slow-dashboard-updates" aria-label="Permalink to &quot;Slow Dashboard Updates&quot;">​</a></h3><ul><li>Reduce the number of widgets on a single dashboard</li><li>Lower chart <code>duration</code> (less history = less rendering)</li><li>Check that stream-based widgets (canvas, terminal) aren&#39;t receiving data faster than they can render</li></ul><h3 id="server-memory-growing" tabindex="-1">Server Memory Growing <a class="header-anchor" href="#server-memory-growing" aria-label="Permalink to &quot;Server Memory Growing&quot;">​</a></h3><p>The server log ring buffer holds 500 entries. If scripts emit large amounts of data via <code>emit()</code> or <code>stream()</code>, this can grow. Check for scripts that emit data in tight loops without a delay.</p><hr><h2 id="getting-more-help" tabindex="-1">Getting More Help <a class="header-anchor" href="#getting-more-help" aria-label="Permalink to &quot;Getting More Help&quot;">​</a></h2><p>If your issue isn&#39;t covered here:</p><ol><li>Check the <a href="#viewing-server-logs">server logs</a> — tray → &quot;View Logs&quot;, or the bottom panel (<code>Ctrl+J</code>) for script output</li><li>Run in CLI mode (<code>node start.js cli</code>) to test drivers directly</li><li>Check the terminal where the server is running for .NET error output</li><li>Report issues at <a href="https://github.com/muxit-io/muxit/issues" target="_blank" rel="noreferrer">github.com/muxit-io/muxit/issues</a></li></ol>`,129)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
